{
  "name": "Innova 300C氩离子激光器",
  "name_en": "Innova 300C Argon Ion Laser",
  "manufacturer": "Coherent",
  "description": "这是一台连续波氩离子气体激光器，属于 Coherent Innova 300C 系列。设备通过气体放电产生可见激光输出，并带有电流、功率、腔内调谐元件和功率跟踪等控制功能，适用于需要稳定可见激光源的光学实验、激光调谐和光谱相关应用。",
  "description_en": "This is a continuous-wave argon ion gas laser in the Coherent Innova 300C series. It produces visible laser output from a gas discharge and provides control over laser current, output power, intracavity tuning elements, and power tracking, making it suitable for optical experiments, laser tuning, and spectroscopy-related laboratory use where a stable visible laser source is needed.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化激光器。",
      "description_en": "Initialize the laser."
    },
    {
      "action_name": "auto-query",
      "description": "向激光器发送查询命令并读取响应。",
      "description_en": "Send a query command to the laser and read back the response."
    },
    {
      "action_name": "auto-baudrate",
      "description": "获取/设置串口波特率。",
      "description_en": "Get/set the serial baud rate."
    },
    {
      "action_name": "auto-faults",
      "description": "获取故障状态。",
      "description_en": "Get the fault status."
    },
    {
      "action_name": "auto-is_in_start_delay",
      "description": "获取是否处于启动延时状态。",
      "description_en": "Get whether the laser is in start-delay state."
    },
    {
      "action_name": "auto-etalon_temperature_setpoint",
      "description": "获取/设置标准具温度设定值。",
      "description_en": "Get/set the etalon temperature setpoint."
    },
    {
      "action_name": "auto-magnetic_field_setpoint_high",
      "description": "获取/设置高磁场设定值。",
      "description_en": "Get/set the high magnetic field setpoint."
    },
    {
      "action_name": "auto-powertrack_position",
      "description": "获取/设置功率跟踪位置。",
      "description_en": "Get/set the power track position."
    },
    {
      "action_name": "auto-recalibrate_powertrack",
      "description": "重新校准功率跟踪。",
      "description_en": "Recalibrate the power tracking system."
    },
    {
      "action_name": "auto-center_powertrack",
      "description": "将功率跟踪调整到中心位置。",
      "description_en": "Center the power tracking system."
    },
    {
      "action_name": "auto-current_setpoint",
      "description": "获取/设置激光电流设定值。",
      "description_en": "Get/set the laser current setpoint."
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "获取/设置激光功率设定值。",
      "description_en": "Get/set the laser power setpoint."
    }
  ],
  "tag_hints": [
    "argon ion laser",
    "continuous-wave gas laser",
    "visible laser source",
    "laser power control",
    "laser current control",
    "intracavity tuning",
    "spectroscopy",
    "optical experiments"
  ]
}

